            'D7',
            'D8'
        ]
    );;
}

test "t1" {
    assert (process_channel_names([]) == []);;
}

test "t2" {
    assert (
        process_channel_names(["EEG Fz", "EEG Cz", "EEG Pz"]) == ["Fz", "Cz", "Pz"]
    );;
}

test "t3" {
    assert (process_channel_names(["Fp1-M1", "Fp1-M2"]) == ["Fp1", "Fp1"]);;
}

test "t4" {
    assert (
        process_channel_names(["EEG Fpz-Cz", "EEG Pz-Oz", "EEG Fpz-Cz", "EEG Pz-Oz"])
        == ["Fpz", "Pz", "Fpz", "Pz"]
    );;
}

