                "EEG F7",
                "EEG F8",
                "EEG T3",
                "EEG T4",
                "EEG P7",
                "EEG P8"
            ]
        )
        == ["O1", "O2", "F7", "F8", "T3", "T4", "P7", "P8"]
    );;
}

