        process_channel_names(
            ["C3", "C4", "Cz", "Pz", "T3", "T4", "F3", "F4", "F7", "F8", "O1", "O2"]
        )
        == ['C3', 'C4', 'Cz', 'Pz', 'T3', 'T4', 'F3', 'F4', 'F7', 'F8', 'O1', 'O2']
